import { makeHtmlLesson, makeCssLesson, makeCodeLesson } from './authoredExpansionBatch1';

const htmlPage = (title, content) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title></head><body>${content}</body></html>`;

const makeCode = (course, title, objective, description, input, output, steps, hint, explanation, checks, starterCode) => makeCodeLesson(course, {
  title, objective, description, input, output, steps, hint, explanation, checks, starterCode,
});

