  3: makeCode('javascript', 'Return the Result: separate calculation from display', 'Return a value from a function and let the caller decide how to display it.', 'Implement `lessonLabel(course)` so it returns `Practice ` followed by the course name. Call the function inside console.log.', 'lessonLabel("CSS")', 'Practice CSS', ['Write lessonLabel with a course parameter.', 'Return the formatted string.', 'Call it from console.log.', 'Do not put console.log inside the function.'], 'return sends a value back; console.log only displays the caller’s chosen value.', 'Keeping a function focused on returning data lets other callers reuse its result in different ways.', ['Return the exact formatted text.', 'Use the supplied course value.', 'Log the call result from outside.', 'Do not return undefined.'], 'function lessonLabel(course) {\n  // Return "Practice " plus course.\n}\n\nconsole.log(lessonLabel("CSS"));'),
  4: makeCode('javascript', 'Local Calculation: keep temporary state inside the function', 'Use a local const for a value that is needed only during one function call.', 'Implement `totalWithBonus(score, bonus)` by calculating a local `total` and returning it. Calls should not share or modify outside state.', 'totalWithBonus(18, 2)', '20', ['Declare total with const inside the function.', 'Set it to score plus bonus.', 'Return the local value.', 'Call the function with different scores.'], 'A local variable exists only while the function call runs.', 'Local state keeps each call independent and avoids hidden changes to variables outside the function.', ['Declare total inside the function.', 'Return score plus bonus.', 'Do not create a global accumulator.', 'Do not change either parameter.'], 'function totalWithBonus(score, bonus) {\n  // Calculate with a local binding and return it.\n}\n\nconsole.log(totalWithBonus(18, 2));'),
