  6: makeCode('javascript', 'Arrow Body: return explicitly from a block', 'Write a block-bodied arrow function with an explicit return statement.', 'Create `makeWelcome` as an arrow function that accepts a name and returns `Welcome, ` followed by the name and an exclamation mark.', 'makeWelcome("Mira")', 'Welcome, Mira!', ['Assign an arrow function to a const.', 'Use a block body with braces.', 'Return the formatted message explicitly.', 'Log the call result.'], 'A block body does not return automatically; write return inside the braces.', 'Arrow functions with block bodies need an explicit return for a value to reach the caller.', ['Use arrow syntax.', 'Include a braced function body.', 'Return the formatted greeting.', 'Do not omit the return statement.'], 'const makeWelcome = name => {\n  // Return the greeting from this block body.\n};\n\nconsole.log(makeWelcome("Mira"));'),
  7: makeCode('javascript', 'Function Expression: store a reusable formatter', 'Assign a function expression to a const binding and call it by that binding.', 'Create `formatCourse` as a function expression that returns the course name in square brackets, such as `[HTML]`.', 'formatCourse("HTML")', '[HTML]', ['Declare formatCourse with const.', 'Assign a function expression with a course parameter.', 'Return the bracketed name.', 'Log the call.'], 'The function expression is assigned to formatCourse, which is the name used for the call.', 'Function expressions can be passed around as values and stored in a binding like other expressions.', ['Use a const function expression.', 'Return square brackets around the input.', 'Call through formatCourse.', 'Do not use an unrelated global function.'], 'const formatCourse = function(course) {\n  // Return the course in square brackets.\n};\n\nconsole.log(formatCourse("HTML"));'),
  8: makeCode('javascript', 'Pure Bonus: return without changing the input', 'Write a pure calculation that returns a new value and leaves its input unchanged.', 'Implement `addBonus(score, bonus)` to return their sum. Do not mutate an object, update a global value, or change either parameter.', 'addBonus(18, 2)', '20', ['Accept score and bonus as parameters.', 'Return their sum.', 'Keep the function free of side effects.', 'Call it twice with different values.'], 'A pure calculation uses its inputs to produce a result without changing outside state.', 'Pure helpers are predictable: the same inputs produce the same result and the caller controls what happens next.', ['Return the sum.', 'Do not change external state.', 'Do not reassign a parameter.', 'Support repeated calls.'], 'function addBonus(score, bonus) {\n  // Return a new total without side effects.\n}\n\nconsole.log(addBonus(18, 2));'),
  9: makeCode('javascript', 'Pass Predicate: return a reusable true-or-false rule', 'Return a boolean from a named predicate function.', 'Implement `isLongLesson(minutes)` and return true when a lesson is at least 30 minutes. Check values 29 and 30.', 'isLongLesson(29), isLongLesson(30)', 'false, true', ['Declare the predicate function.', 'Compare minutes with 30 using >=.', 'Return the boolean result.', 'Log both boundary examples.'], 'The predicate’s comparison expression already produces a boolean value.', 'A predicate names a decision and can be reused wherever the same rule is needed.', ['Use an inclusive 30-minute threshold.', 'Return false for 29.', 'Return true for 30.', 'Do not return text labels.'], 'function isLongLesson(minutes) {\n  // Return whether the duration reaches 30 minutes.\n}\n\nconsole.log(isLongLesson(29));\nconsole.log(isLongLesson(30));'),
  10: makeCode('javascript', 'Early Greeting: return from a guard clause', 'Use a guard clause to handle a missing name before building the regular result.', 'Implement `greeting(name)` so an empty string returns `Welcome, guest!`; otherwise return `Welcome, ` plus the name and `!`.', 'greeting(""), greeting("Mira")', 'Welcome, guest!; Welcome, Mira!', ['Check for an empty name at the start.', 'Return the guest message immediately for that case.', 'Return a personalized message for other names.', 'Do not add an unnecessary else after the early return.'], 'An early return ends that function call, so the normal path can remain at the end.', 'Guard clauses make exceptional or fallback cases visible before the main behavior.', ['Return the guest message for an empty string.', 'Return a personalized message for a supplied name.', 'Use early return for the empty case.', 'Do not mutate the input.'], 'function greeting(name) {\n  // Add an empty-name guard, then return a personal greeting.\n}\n\nconsole.log(greeting(""));\nconsole.log(greeting("Mira"));'),
